class MaxHeap {
  private a: number[] = [];
  get size() { return this.a.length; }
  push(v: number): void {
    const a = this.a;
    a.push(v);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (a[p] >= a[i]) break;
      [a[p], a[i]] = [a[i], a[p]];
      i = p;
    }
  }
  pop(): number {
    const a = this.a, top = a[0], last = a.pop()!;
    if (a.length) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < a.length && a[l] > a[m]) m = l;
        if (r < a.length && a[r] > a[m]) m = r;
        if (m === i) break;
        [a[m], a[i]] = [a[i], a[m]];
        i = m;
      }
    }
    return top;
  }
  values(): number[] { return this.a; }
}

function coinsAfterRoots(stacks: number[], k: number): number {
  const h = new MaxHeap();
  for (const s of stacks) h.push(s);
  for (let round = 0; round < k; round++) {
    const v = h.pop();
    h.push(Math.floor(Math.sqrt(v)));
    if (v === 1) break; // every stack is 1 now
  }
  return h.values().reduce((s, v) => s + v, 0);
}

