class Solution:
    def coinsAfterRoots(self, stacks: List[int], k: int) -> int:
        heap = [-s for s in stacks]  # negate for a max-heap
        heapq.heapify(heap)
        for _ in range(k):
            v = -heap[0]
            if v == 1:
                break
            heapq.heapreplace(heap, -math.isqrt(v))
        return -sum(heap)

